import ast
import os
import glob

def check_function_for_write(node, source_code):
    # Get the source of the function
    func_source = ast.get_source_segment(source_code, node)
    if not func_source:
        return False, []

    indicators = ['create_', 'update_', 'delete_', 'save_', 'write_', 'POST', 'PUT', 'PATCH']
    found = [ind for ind in indicators if ind in func_source]
    return len(found) > 0, found

def find_legacy_auth_calls():
    py_files = glob.glob('app/**/*.py', recursive=True)
    for path in sorted(py_files):
        if path == 'app/auth.py':
            continue
        with open(path, 'r', encoding='utf-8') as f:
            source = f.read()
        try:
            tree = ast.parse(source)
        except Exception as e:
            print(f"Error parsing {path}: {e}")
            continue

        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                # Check if this function calls legacy_auth
                has_legacy_auth = False
                for subnode in ast.walk(node):
                    if isinstance(subnode, ast.Call) and isinstance(subnode.func, ast.Name) and subnode.func.id == 'legacy_auth':
                        has_legacy_auth = True
                        break
                if has_legacy_auth:
                    is_write, found = check_function_for_write(node, source)
                    print(f"{path}:::{node.name}:::{is_write}:::{found}")

if __name__ == '__main__':
    find_legacy_auth_calls()

import ast
import os
import glob

def find_details():
    py_files = glob.glob('app/**/*.py', recursive=True)
    for path in sorted(py_files):
        if path == 'app/auth.py':
            continue
        with open(path, 'r', encoding='utf-8') as f:
            source = f.read()
        try:
            tree = ast.parse(source)
        except Exception as e:
            continue

        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                has_legacy_auth = False
                for subnode in ast.walk(node):
                    if isinstance(subnode, ast.Call) and isinstance(subnode.func, ast.Name) and subnode.func.id == 'legacy_auth':
                        has_legacy_auth = True
                        break
                if has_legacy_auth:
                    # Look at what is inside this function
                    args = [arg.arg for arg in node.args.args]
                    # Find all return dict keys or return statements
                    returns = []
                    for subnode in ast.walk(node):
                        if isinstance(subnode, ast.Return):
                            returns.append(ast.unparse(subnode.value) if subnode.value else 'None')
                    print(f"Path: {path}")
                    print(f"  Func: {node.name}")
                    print(f"  Args: {args}")
                    print(f"  Returns: {returns}")

if __name__ == '__main__':
    find_details()
